package org.slavicmyths.skim;
import java.util.*;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.saveddata.SavedData;
import org.slavicmyths.bogatyr.*;
import org.slavicmyths.marinka.*;
import org.slavicmyths.finist.*;
/** Supplements existing canonical UUID maps with recalled snapshots; never loads distant chunks. */
public final class HeroCalls extends SavedData {
 public final Map<UUID,UUID> alyosha=new HashMap<>(),finist=new HashMap<>();
 public final Map<String,CompoundTag> resting=new HashMap<>();
 public final Map<UUID,CompoundTag> dormant=new HashMap<>(),finistDormant=new HashMap<>();
 public final Set<UUID> retired=new HashSet<>();
 private final Map<UUID,Long> departures=new HashMap<>();
 private final Map<String,CompoundTag> lifecycles=new HashMap<>();
 private static final long HELP_TICKS=12000L, COOLDOWN_TICKS=36000L;
 private static String key(UUID owner,String id){return owner+"/"+id;}
 private static long clock(ServerLevel w){return w.getServer().overworld().getGameTime();}
 private static UUID heroOwner(LivingEntity h){return h instanceof IlyaEntity a?a.owner:h instanceof DobrynyaEntity a?a.owner:h instanceof AlyoshaEntity a?a.owner:h instanceof FinistEntity a?a.owner:null;}
 private static String heroId(LivingEntity h){return h instanceof IlyaEntity?"ilya_muromets":h instanceof DobrynyaEntity?"dobrynya_nikitich":h instanceof AlyoshaEntity?"alyosha_popovich":h instanceof FinistEntity?"finist":null;}
 private CompoundTag lifecycle(UUID owner,String id){return lifecycles.computeIfAbsent(key(owner,id),k->new CompoundTag());}
 public static boolean available(ServerPlayer p,String id){var n=get(p.serverLevel()).lifecycle(p.getUUID(),id);long remaining=n.getLong("ReadyAt")-clock(p.serverLevel());if(remaining<=0)return true;p.sendSystemMessage(net.minecraft.network.chat.Component.literal("Повторный призыв этого богатыря через "+((remaining+19)/20)+" сек."));return false;}
 public static void summoned(ServerPlayer p,String id,LivingEntity h){var d=get(p.serverLevel());var n=d.lifecycle(p.getUUID(),id);n.putUUID("Owner",p.getUUID());n.putUUID("Entity",h.getUUID());n.putString("Hero",id);n.putLong("ExpiresAt",clock(p.serverLevel())+HELP_TICKS);n.putLong("ReadyAt",0);n.putInt("Recoveries",0);n.putBoolean("Active",true);h.getPersistentData().remove("HeroRecoveryMarked");d.setDirty();}
 public static void rebound(ServerLevel w,UUID owner,String id,LivingEntity h){var d=get(w);var n=d.lifecycle(owner,id);if(n.getBoolean("Active")){n.putUUID("Entity",h.getUUID());d.setDirty();}}
 public static boolean beginRecovery(LivingEntity h){if(!(h.level() instanceof ServerLevel w))return false;UUID owner=heroOwner(h);String id=heroId(h);if(owner==null||id==null)return false;var d=get(w);if(!h.getUUID().equals(map(w,id).get(owner)))return false;if(h.getPersistentData().getBoolean("HeroRecoveryMarked"))return true;var n=d.lifecycle(owner,id);if(!n.getBoolean("Active")){n.putUUID("Owner",owner);n.putUUID("Entity",h.getUUID());n.putString("Hero",id);n.putLong("ExpiresAt",clock(w)+HELP_TICKS);n.putBoolean("Active",true);}if(n.getInt("Recoveries")>=2)return false;n.putInt("Recoveries",n.getInt("Recoveries")+1);h.getPersistentData().putBoolean("HeroRecoveryMarked",true);d.setDirty();return true;}
 public static void recovered(LivingEntity h){h.getPersistentData().remove("HeroRecoveryMarked");}
 private static void end(LivingEntity h,boolean remove){if(!(h.level() instanceof ServerLevel w))return;UUID owner=heroOwner(h);String id=heroId(h);if(owner==null||id==null)return;var d=get(w);var map=map(w,id);if(!h.getUUID().equals(map.get(owner)))return;var n=d.lifecycle(owner,id);n.putUUID("Owner",owner);n.putString("Hero",id);n.putBoolean("Active",false);n.putLong("ReadyAt",clock(w)+COOLDOWN_TICKS);map.remove(owner,h.getUUID());d.resting.remove(key(owner,id));d.dormant.remove(owner);d.finistDormant.remove(owner);d.departures.remove(h.getUUID());d.setDirty();dirty(w);if(remove){h.getPersistentData().putBoolean("HeroRecalling",true);if(h instanceof Mob m){m.setTarget(null);m.getNavigation().stop();}h.discard();}}
 public static void retire(LivingEntity h){end(h,true);}
 public static void defeated(LivingEntity h){end(h,false);}
 public static void recalled(LivingEntity h){if(!(h.level() instanceof ServerLevel w))return;UUID owner=heroOwner(h);String id=heroId(h);if(owner==null||id==null)return;var d=get(w);var n=d.lifecycle(owner,id);n.putBoolean("Active",false);n.putLong("ReadyAt",clock(w)+COOLDOWN_TICKS);d.setDirty();}
 public void tickLifecycles(net.minecraft.server.MinecraftServer server){long now=server.overworld().getGameTime();if(now%20!=0)return;for(var id:List.of("ilya_muromets","dobrynya_nikitich","alyosha_popovich","finist"))for(var entry:new HashMap<>(map(server.overworld(),id)).entrySet())if(!lifecycles.containsKey(key(entry.getKey(),id))){var n=lifecycle(entry.getKey(),id);n.putUUID("Owner",entry.getKey());n.putUUID("Entity",entry.getValue());n.putString("Hero",id);n.putLong("ExpiresAt",now+HELP_TICKS);n.putBoolean("Active",true);setDirty();}for(var entry:new ArrayList<>(lifecycles.entrySet())){var n=entry.getValue();if(!n.getBoolean("Active")||!n.hasUUID("Owner")||!n.hasUUID("Entity"))continue;UUID owner=n.getUUID("Owner"),entityId=n.getUUID("Entity");String id=n.getString("Hero");if(!entityId.equals(map(server.overworld(),id).get(owner))){n.putBoolean("Active",false);n.putLong("ReadyAt",now+COOLDOWN_TICKS);setDirty();continue;}var player=server.getPlayerList().getPlayer(owner);if(player!=null&&player.isAlive()&&battleLocked(player)){n.putLong("ExpiresAt",n.getLong("ExpiresAt")+20);setDirty();continue;}if(now<n.getLong("ExpiresAt"))continue;LivingEntity found=null;for(var level:server.getAllLevels())if(level.getEntity(entityId) instanceof LivingEntity h){found=h;break;}if(found!=null)retire(found);else{map(server.overworld(),id).remove(owner,entityId);n.putBoolean("Active",false);n.putLong("ReadyAt",now+COOLDOWN_TICKS);dormant.remove(owner);finistDormant.remove(owner);resting.remove(key(owner,id));setDirty();dirty(server.overworld());}}}

 public static HeroCalls get(ServerLevel w){return w.getServer().overworld().getDataStorage().computeIfAbsent(new Factory<>(HeroCalls::new,HeroCalls::load),"slavicmyths_hero_calls_173");}
 public static HeroCalls load(CompoundTag n,HolderLookup.Provider p){var d=new HeroCalls();for(var t:n.getList("Alyosha",Tag.TAG_COMPOUND)){var a=(CompoundTag)t;d.alyosha.put(a.getUUID("Owner"),a.getUUID("Entity"));}for(var t:n.getList("Finist",Tag.TAG_COMPOUND)){var a=(CompoundTag)t;d.finist.put(a.getUUID("Owner"),a.getUUID("Entity"));}var s=n.getCompound("Resting");for(var k:s.getAllKeys())d.resting.put(k,s.getCompound(k));s=n.getCompound("Dormant");for(var k:s.getAllKeys())d.dormant.put(UUID.fromString(k),s.getCompound(k));s=n.getCompound("FinistDormant");for(var k:s.getAllKeys())d.finistDormant.put(UUID.fromString(k),s.getCompound(k));for(var t:n.getList("Retired",Tag.TAG_STRING))d.retired.add(UUID.fromString(t.getAsString()));s=n.getCompound("HeroLifecycles");for(var k:s.getAllKeys())d.lifecycles.put(k,s.getCompound(k));return d;}
 @Override public CompoundTag save(CompoundTag n,HolderLookup.Provider p){var a=new ListTag();alyosha.forEach((k,v)->{var t=new CompoundTag();t.putUUID("Owner",k);t.putUUID("Entity",v);a.add(t);});n.put("Alyosha",a);var fs=new ListTag();finist.forEach((k,v)->{var t=new CompoundTag();t.putUUID("Owner",k);t.putUUID("Entity",v);fs.add(t);});n.put("Finist",fs);var s=new CompoundTag();resting.forEach(s::put);n.put("Resting",s);s=new CompoundTag();for(var e:dormant.entrySet())s.put(e.getKey().toString(),e.getValue());n.put("Dormant",s);var fd=new CompoundTag();for(var e:finistDormant.entrySet())fd.put(e.getKey().toString(),e.getValue());n.put("FinistDormant",fd);var retiredTags=new ListTag();retired.forEach(id->retiredTags.add(StringTag.valueOf(id.toString())));n.put("Retired",retiredTags);var live=new CompoundTag();lifecycles.forEach(live::put);n.put("HeroLifecycles",live);return n;}
 public static Map<UUID,UUID> map(ServerLevel w,String id){return switch(id){case "ilya_muromets"->BogatyrLedger.get(w).heroes;case "dobrynya_nikitich"->WitchYard.get(w.getServer().overworld()).heroes;case "finist"->get(w).finist;default->get(w).alyosha;};}
 public static boolean battleLocked(ServerPlayer p){var v=SkimValley.get(p.serverLevel());var near=v.near(p.position());var y=WitchYard.get(p.serverLevel().getServer().overworld());var yard=y.near(p.position());return org.slavicmyths.kalin.KalinEncounter.get(p.serverLevel()).owner(p.getUUID())!=null||org.slavicmyths.kalin.KalinEncounter.get(p.serverLevel()).nearBattle(p.serverLevel(),p.position())||KartausEncounter.get(p.serverLevel()).owner(p.getUUID())!=null||KartausEncounter.get(p.serverLevel()).near(p.serverLevel(),p.position())||v.lock(p.getUUID())!=null||(near!=null&&(near.status==SkimValley.Status.STARTING||near.status==SkimValley.Status.ACTIVE))||y.lock(p.getUUID())!=null||(yard!=null&&yard.status==WitchYard.Status.COMBAT)||BogatyrLedger.active(p);}
 public static int count(ServerPlayer p){int n=0;for(var id:List.of("ilya_muromets","dobrynya_nikitich","alyosha_popovich","finist"))if(map(p.serverLevel(),id).containsKey(p.getUUID()))n++;return n;}
 public static Entity loaded(ServerPlayer p,String id){var uuid=map(p.serverLevel(),id).get(p.getUUID());if(uuid==null)return null;for(var w:p.serverLevel().getServer().getAllLevels()){var e=w.getEntity(uuid);if(e!=null)return e;}return null;}
 public static void dirty(ServerLevel w){get(w).setDirty();BogatyrLedger.get(w).setDirty();WitchYard.get(w.getServer().overworld()).setDirty();}
 public static void message(ServerPlayer p,String k){long now=p.level().getGameTime();var n=p.getPersistentData();if(now<n.getLong("HeroCallMessageUntil"))return;n.putLong("HeroCallMessageUntil",now+60);p.sendSystemMessage(net.minecraft.network.chat.Component.translatable("message.slavicmyths."+k));}
 public static void messageOwner(AlyoshaEntity a,String k){if(a.level() instanceof ServerLevel w&&a.owner!=null){var p=w.getServer().getPlayerList().getPlayer(a.owner);if(p!=null)message(p,k);}}
 public static boolean safeSpot(ServerLevel w,net.minecraft.world.phys.Vec3 at,double width,double height){if(at==null)return false;var box=new net.minecraft.world.phys.AABB(at.x-width/2,at.y,at.z-width/2,at.x+width/2,at.y+height,at.z+width/2);for(var q:net.minecraft.core.BlockPos.betweenClosed(net.minecraft.core.BlockPos.containing(box.minX,box.minY,box.minZ),net.minecraft.core.BlockPos.containing(box.maxX-.001,box.maxY-.001,box.maxZ-.001))){if(!w.hasChunkAt(q)||!w.getWorldBorder().isWithinBounds(q)||!w.getFluidState(q).isEmpty()||w.getBlockState(q).is(net.minecraft.world.level.block.Blocks.FIRE)||w.getBlockState(q).is(net.minecraft.world.level.block.Blocks.SOUL_FIRE)||w.getBlockState(q).is(net.minecraft.world.level.block.Blocks.WITHER_ROSE)||w.getBlockState(q).is(net.minecraft.world.level.block.Blocks.SWEET_BERRY_BUSH))return false;if(q.getY()==net.minecraft.core.BlockPos.containing(at).getY()&&!org.slavicmyths.sivka.SivkaWhistle.safeFloor(w,q.below()))return false;}return w.noCollision(box);}
 public static void sleep(AlyoshaEntity a){if(a.owner==null||!(a.level() instanceof ServerLevel w))return;var n=new CompoundTag();a.saveWithoutId(n);get(w).dormant.put(a.owner,n);get(w).setDirty();a.discard();}
 public static void sleepFinist(FinistEntity f){if(f.owner==null||!(f.level() instanceof ServerLevel w))return;var n=new CompoundTag();f.saveWithoutId(n);get(w).finistDormant.put(f.owner,n);get(w).setDirty();f.discard();}
 public void recover(ServerLevel w){if(w.getGameTime()%20==0)for(var entry:new ArrayList<>(finistDormant.entrySet())){var p=w.getServer().getPlayerList().getPlayer(entry.getKey());if(p==null||!lifecycles.getOrDefault(key(p.getUUID(),"finist"),new CompoundTag()).getBoolean("Active"))continue;var n=entry.getValue();n.putFloat("Health",Math.min(119,n.getFloat("Health")+8));setDirty();if(org.slavicmyths.kalin.KalinEncounter.get(w).owner(p.getUUID())!=null||KartausEncounter.get(w).owner(p.getUUID())!=null||n.getFloat("Health")<119)continue;var at=BogatyrLedger.safe(p.serverLevel(),p.position(),.76,3,3);if(!safeSpot(p.serverLevel(),at,.76,2.25))continue;var f=FinistContent.FINIST.get().create(p.serverLevel());f.load(n);f.encounter=null;f.moveTo(at.x,at.y,at.z,p.getYRot()+180,0);if(p.serverLevel().addFreshEntity(f)){finist.put(p.getUUID(),f.getUUID());rebound(w,p.getUUID(),"finist",f);finistDormant.remove(p.getUUID());setDirty();}}if(w.getGameTime()%40!=0)return;for(var entry:new ArrayList<>(dormant.entrySet())){var p=w.getServer().getPlayerList().getPlayer(entry.getKey());if(p==null||!lifecycles.getOrDefault(key(p.getUUID(),"alyosha_popovich"),new CompoundTag()).getBoolean("Active"))continue;var n=entry.getValue();n.putFloat("Health",Math.min(122.5F,n.getFloat("Health")+4));setDirty();if(org.slavicmyths.kalin.KalinEncounter.get(w).owner(p.getUUID())!=null||SkimValley.get(w).lock(p.getUUID())!=null)continue;var at=BogatyrLedger.safe(p.serverLevel(),p.position(),.72,3,3);if(at==null)continue;var h=SkimContent.ALYOSHA.get().create(p.serverLevel());h.load(n);h.arena=null;h.moveTo(at.x,at.y,at.z,p.getYRot()+180,0);if(p.serverLevel().addFreshEntity(h)){alyosha.put(p.getUUID(),h.getUUID());rebound(w,p.getUUID(),"alyosha_popovich",h);dormant.remove(p.getUUID());setDirty();}}}
 public void reconcile(Entity e){if(!e.getPersistentData().getBoolean("HeroRecalling")||!(e.level() instanceof ServerLevel w))return;UUID owner=e instanceof IlyaEntity a?a.owner:e instanceof DobrynyaEntity a?a.owner:e instanceof AlyoshaEntity a?a.owner:e instanceof FinistEntity a?a.owner:null;if(owner==null)return;String id=e instanceof IlyaEntity?"ilya_muromets":e instanceof DobrynyaEntity?"dobrynya_nikitich":e instanceof FinistEntity?"finist":"alyosha_popovich";if(resting.containsKey(owner+"/"+id))departures.put(e.getUUID(),w.getGameTime()+1);}
 public static boolean toggle(ServerPlayer p,String id){
  if(!p.isAlive()||p.isSpectator())return false;
  var w=p.serverLevel();var d=get(w);var maps=map(w,id);String key=p.getUUID()+"/"+id;
  if(maps.containsKey(p.getUUID())){
   if(battleLocked(p)){message(p,"summon.battle_locked");return false;}
   var e=loaded(p,id);if(!(e instanceof LivingEntity h)||e.level()!=w||d.departures.containsKey(e.getUUID())){message(p,"summon.already_present");return false;}
   var n=new CompoundTag();h.saveWithoutId(n);d.resting.put(key,n);recalled(h);d.departures.put(e.getUUID(),w.getGameTime()+18);h.getPersistentData().putBoolean("HeroRecalling",true);if(h instanceof Mob m){m.getNavigation().stop();m.setTarget(null);}if(h instanceof AlyoshaEntity a)a.begin(SkimAction.RECALL);if(h instanceof FinistEntity a)a.begin(FalconAction.RECALL);d.setDirty();return true;
  }
  if(!StoryPolicy.canSummon(p,id)||!available(p,id))return false;
  boolean polozParty=org.slavicmyths.poloz.PolozEvent.active(w)&&!id.equals("finist");
  if(count(p)>=(polozParty?3:2)){message(p,"summon.party_full");return false;}
  if(id.equals("dobrynya_nikitich")&&!org.slavicmyths.progression.Knowledge.knows(p,"first_book_entry")&&!p.getInventory().contains(new net.minecraft.world.item.ItemStack(org.slavicmyths.registry.ModItems.LORE_BOOK.get()))&&!p.hasPermissions(2)){message(p,"summon.locked");return false;}
  float width=id.equals("finist")?.76F:id.equals("ilya_muromets")?.93F:id.equals("dobrynya_nikitich")?.8F:.72F;float height=id.equals("finist")?2.2F:id.equals("ilya_muromets")?2.45F:id.equals("dobrynya_nikitich")?2.2F:2.15F;
  var at=BogatyrLedger.safe(w,p.position(),width,Math.max(3,height),3);if(!safeSpot(w,at,width,Math.max(3,height))){message(p,"summon.unsafe");return false;}
  LivingEntity h=switch(id){case "ilya_muromets"->BogatyrContent.ILYA.get().create(w);case "dobrynya_nikitich"->MarinkaContent.DOBRYNYA.get().create(w);case "finist"->FinistContent.FINIST.get().create(w);default->SkimContent.ALYOSHA.get().create(w);};if(h==null)return false;
  var snapshot=d.resting.get(key);if(snapshot!=null)h.load(snapshot.copy());h.setUUID(UUID.randomUUID());h.getPersistentData().remove("HeroRecalling");
  if(h instanceof FinistEntity a){a.owner=p.getUUID();}if(h instanceof IlyaEntity a)a.owner=p.getUUID();if(h instanceof DobrynyaEntity a)a.owner=p.getUUID();if(h instanceof AlyoshaEntity a){a.owner=p.getUUID();}
  h.moveTo(at.x,at.y,at.z,p.getYRot()+180,0);if(!w.addFreshEntity(h))return false;maps.put(p.getUUID(),h.getUUID());d.resting.remove(key);summoned(p,id,h);dirty(w);return true;
 }
 public void departures(net.minecraft.server.MinecraftServer server){long now=server.overworld().getGameTime();for(var entry:new ArrayList<>(departures.entrySet())){if(now<entry.getValue())continue;Entity entity=null;for(var w:server.getAllLevels()){var found=w.getEntity(entry.getKey());if(found!=null){entity=found;break;}}if(entity!=null){UUID owner=entity instanceof IlyaEntity a?a.owner:entity instanceof DobrynyaEntity a?a.owner:entity instanceof AlyoshaEntity a?a.owner:entity instanceof FinistEntity a?a.owner:null;String id=entity instanceof IlyaEntity?"ilya_muromets":entity instanceof DobrynyaEntity?"dobrynya_nikitich":entity instanceof FinistEntity?"finist":"alyosha_popovich";if(owner!=null)map(server.overworld(),id).remove(owner,entry.getKey());entity.discard();}else{for(var snap:resting.entrySet())if(snap.getValue().hasUUID("UUID")&&entry.getKey().equals(snap.getValue().getUUID("UUID"))){var pieces=snap.getKey().split("/");map(server.overworld(),pieces[1]).remove(UUID.fromString(pieces[0]),entry.getKey());retired.add(entry.getKey());break;}}departures.remove(entry.getKey());dirty(server.overworld());}}
}
